'use client';

import React from 'react';

interface WeatherData {
  type: string;
  location: string;
  current: {
    temperature: number;
    condition: string;
    humidity: number;
    wind_speed: number;
  };
  forecast: Array<{
    day: string;
    high: number;
    low: number;
    condition: string;
  }>;
}

interface WeatherCardProps {
  data: WeatherData;
}

const WeatherCard: React.FC<WeatherCardProps> = ({ data }) => {
  const getWeatherIcon = (condition: string) => {
    const icons: { [key: string]: string } = {
      'Sunny': '☀️',
      'Partly Cloudy': '⛅',
      'Cloudy': '☁️',
      'Rainy': '🌧️',
      'Stormy': '⛈️',
      'Snowy': '❄️',
    };
    return icons[condition] || '🌤️';
  };

  return (
    <div className="bg-gradient-to-br from-blue-50 to-blue-100 dark:from-blue-900 dark:to-blue-800 rounded-xl p-6 shadow-lg border border-blue-200 dark:border-blue-700 my-4">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-xl font-bold text-blue-800 dark:text-blue-100">
          Weather in {data.location}
        </h3>
        <span className="text-3xl">{getWeatherIcon(data.current.condition)}</span>
      </div>
      
      {/* Current Weather */}
      <div className="bg-white dark:bg-blue-950 rounded-lg p-4 mb-6 shadow-sm">
        <div className="flex items-center justify-between mb-3">
          <div>
            <p className="text-3xl font-bold text-blue-800 dark:text-blue-100">
              {data.current.temperature}°F
            </p>
            <p className="text-blue-600 dark:text-blue-300 font-medium">
              {data.current.condition}
            </p>
          </div>
          <div className="text-sm text-blue-600 dark:text-blue-300 space-y-1">
            <div className="flex items-center gap-2">
              <span>💧</span>
              <span>Humidity: {data.current.humidity}%</span>
            </div>
            <div className="flex items-center gap-2">
              <span>💨</span>
              <span>Wind: {data.current.wind_speed} mph</span>
            </div>
          </div>
        </div>
      </div>

      {/* 5-Day Forecast */}
      <div>
        <h4 className="text-lg font-semibold text-blue-800 dark:text-blue-100 mb-3">
          5-Day Forecast
        </h4>
        <div className="grid grid-cols-5 gap-2">
          {data.forecast.map((day, index) => (
            <div
              key={index}
              className="bg-white dark:bg-blue-950 rounded-lg p-3 text-center shadow-sm hover:shadow-md transition-shadow"
            >
              <p className="text-xs font-medium text-blue-600 dark:text-blue-300 mb-1">
                {day.day}
              </p>
              <div className="text-lg mb-1">{getWeatherIcon(day.condition)}</div>
              <p className="text-sm font-bold text-blue-800 dark:text-blue-100">
                {day.high}°
              </p>
              <p className="text-xs text-blue-500 dark:text-blue-400">
                {day.low}°
              </p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default WeatherCard; 