'use client';

import React, { useState } from 'react';

interface Message {
  role: string;
  content: string;
  timestamp?: string;
}

interface Chat {
  id: string;
  title: string;
  messages: Message[];
  lastUpdated: string;
}

interface SidebarProps {
  chats: Chat[];
  currentChatId: string | null;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
  onSelectChat: (chatId: string) => void;
  onNewChat: () => void;
  onDeleteChat: (chatId: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({
  chats,
  currentChatId,
  isCollapsed,
  onToggleCollapse,
  onSelectChat,
  onNewChat,
  onDeleteChat,
}) => {
  const [hoveredChatId, setHoveredChatId] = useState<string | null>(null);

  const getChatTitle = (chat: Chat) => {
    if (chat.title) return chat.title;
    const firstUserMessage = chat.messages.find(m => m.role === 'user');
    return firstUserMessage?.content.slice(0, 30) + '...' || 'New Chat';
  };

  const formatLastUpdated = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffInHours = (now.getTime() - date.getTime()) / (1000 * 60 * 60);
    
    if (diffInHours < 1) return 'Just now';
    if (diffInHours < 24) return `${Math.floor(diffInHours)}h ago`;
    if (diffInHours < 48) return 'Yesterday';
    return date.toLocaleDateString();
  };

  return (
    <div className={`
      bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700 
      transition-all duration-300 flex flex-col h-screen
      ${isCollapsed ? 'w-16' : 'w-80'}
    `}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
        {!isCollapsed && (
          <h2 className="text-lg font-semibold text-gray-800 dark:text-gray-200">
            Chat History
          </h2>
        )}
        <button
          onClick={onToggleCollapse}
          className="p-2 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
          title={isCollapsed ? 'Expand sidebar' : 'Collapse sidebar'}
        >
          <svg
            className={`w-5 h-5 transition-transform ${isCollapsed ? 'rotate-180' : ''}`}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 19l-7-7 7-7m8 14l-7-7 7-7" />
          </svg>
        </button>
      </div>

      {/* New Chat Button */}
      <div className="p-4">
        <button
          onClick={onNewChat}
          className={`
            w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 rounded-lg 
            transition-colors flex items-center justify-center gap-2
            ${isCollapsed ? 'px-2' : 'px-4'}
          `}
          title="Start new chat"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          {!isCollapsed && <span>New Chat</span>}
        </button>
      </div>

      {/* Chat List */}
      <div className="flex-1 overflow-y-auto">
        {chats.length === 0 ? (
          !isCollapsed && (
            <div className="p-4 text-center text-gray-500 dark:text-gray-400">
              <p className="text-sm">No chats yet</p>
              <p className="text-xs mt-1">Start a new conversation</p>
            </div>
          )
        ) : (
          <div className="space-y-1 p-2">
            {chats.map((chat) => (
              <div
                key={chat.id}
                className="relative group"
                onMouseEnter={() => setHoveredChatId(chat.id)}
                onMouseLeave={() => setHoveredChatId(null)}
              >
                <button
                  onClick={() => onSelectChat(chat.id)}
                  className={`
                    w-full text-left p-3 rounded-lg transition-colors border
                    ${currentChatId === chat.id
                      ? 'bg-blue-100 dark:bg-blue-900 border-blue-300 dark:border-blue-600'
                      : 'hover:bg-gray-100 dark:hover:bg-gray-800 border-transparent'
                    }
                    ${isCollapsed ? 'px-2' : ''}
                  `}
                  title={isCollapsed ? getChatTitle(chat) : undefined}
                >
                  {isCollapsed ? (
                    <div className="flex justify-center">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
                      </svg>
                    </div>
                  ) : (
                    <div>
                      <p className="font-medium text-gray-800 dark:text-gray-200 truncate">
                        {getChatTitle(chat)}
                      </p>
                      <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                        {formatLastUpdated(chat.lastUpdated)}
                      </p>
                    </div>
                  )}
                </button>

                {/* Delete Button */}
                {!isCollapsed && hoveredChatId === chat.id && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      onDeleteChat(chat.id);
                    }}
                    className="absolute right-2 top-1/2 transform -translate-y-1/2 p-1 rounded hover:bg-red-100 dark:hover:bg-red-900 text-red-600 dark:text-red-400 transition-colors"
                    title="Delete chat"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Sidebar; 