'use client';

import React from 'react';

interface StockData {
  type: string;
  symbol: string;
  current_price: number;
  change: string;
  change_percent: string;
  price_history: Array<{
    date: string;
    price: number;
  }>;
}

interface StockCardProps {
  data: StockData;
}

const StockCard: React.FC<StockCardProps> = ({ data }) => {
  const isPositive = data.change.startsWith('+');
  const maxPrice = Math.max(...data.price_history.map(p => p.price));
  const minPrice = Math.min(...data.price_history.map(p => p.price));

  const getBarHeight = (price: number) => {
    const range = maxPrice - minPrice;
    const percentage = range === 0 ? 50 : ((price - minPrice) / range) * 60 + 20;
    return `${percentage}%`;
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  };

  return (
    <div className="bg-gradient-to-br from-green-50 to-emerald-100 dark:from-green-900 dark:to-emerald-800 rounded-xl p-6 shadow-lg border border-green-200 dark:border-green-700 my-4">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-xl font-bold text-green-800 dark:text-green-100">
          {data.symbol} Stock
        </h3>
        <span className="text-2xl">📈</span>
      </div>
      
      {/* Current Price */}
      <div className="bg-white dark:bg-green-950 rounded-lg p-4 mb-6 shadow-sm">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-3xl font-bold text-green-800 dark:text-green-100">
              ${data.current_price.toFixed(2)}
            </p>
            <p className="text-sm text-gray-600 dark:text-gray-300">
              Current Price
            </p>
          </div>
          <div className="text-right">
            <p className={`text-lg font-semibold ${
              isPositive ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'
            }`}>
              {data.change}
            </p>
            <p className={`text-sm ${
              isPositive ? 'text-green-500 dark:text-green-500' : 'text-red-500 dark:text-red-500'
            }`}>
              {data.change_percent}
            </p>
          </div>
        </div>
      </div>

      {/* Price History Chart */}
      <div>
        <h4 className="text-lg font-semibold text-green-800 dark:text-green-100 mb-3">
          10-Day Price History
        </h4>
        <div className="bg-white dark:bg-green-950 rounded-lg p-4 shadow-sm">
          <div className="flex items-end justify-between h-32 gap-1">
            {data.price_history.map((entry, index) => (
              <div key={index} className="flex flex-col items-center flex-1">
                <div
                  className="w-full bg-gradient-to-t from-green-500 to-green-300 dark:from-green-600 dark:to-green-400 rounded-t-sm min-h-[4px] transition-all hover:opacity-80"
                  style={{ height: getBarHeight(entry.price) }}
                  title={`${formatDate(entry.date)}: $${entry.price.toFixed(2)}`}
                />
                <p className="text-xs text-green-600 dark:text-green-300 mt-1 transform -rotate-45 origin-bottom-left">
                  {formatDate(entry.date)}
                </p>
              </div>
            ))}
          </div>
          
          {/* Price range indicators */}
          <div className="flex justify-between text-xs text-gray-500 dark:text-gray-400 mt-2 pt-2 border-t border-gray-200 dark:border-gray-600">
            <span>Low: ${minPrice.toFixed(2)}</span>
            <span>High: ${maxPrice.toFixed(2)}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StockCard; 